import{z as p,x as E,o as s,c as B,q as i,j as o,D as t,d as r,s as n,S as d,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Floyd–Warshall","description":"","frontmatter":{"title":"Floyd–Warshall","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/floyd-warshall.md","filePath":"cs/floyd-warshall.md","lastUpdated":1791413859000}'),h={name:"cs/floyd-warshall.md"};function k(m,a,D,A,f,V){const e=E("Mermaid");return s(),B("div",null,[a[2]||(a[2]=i('<h1 id="floyd–warshall" tabindex="-1">Floyd–Warshall <a class="header-anchor" href="#floyd–warshall" aria-label="Permalink to &quot;Floyd–Warshall&quot;">​</a></h1><div class="epigraph"><p>允许中间点集合逐步扩大到 $V$，三维递推给出全部点对的最短路。</p><footer>—— 据 Floyd, Algorithm 97: Shortest Path, 1962；Warshall, A Theorem on Boolean Matrices, 1962；CLRS 第 25 章整理</footer></div><p>上一课<a href="/cs/diff-constraint">差分约束</a>解决带负边的<strong>单源</strong>。全源若跑 \\(|V|\\) 次，非负时 Dijkstra、一般时 Bellman–Ford，分别是 \\(O(VE\\log V)\\) 与 \\(O(V^2E)\\) 量级。本课不重写松弛循环。缺口是：在邻接矩阵上用<strong>中间点集合</strong>做动态规划，一次 \\(O(V^3)\\) 得到全部 \\(\\delta(i,j)\\)。本课只钉这个递推；背包式 DP 的一般模板在更后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(d_{ij}^{(k)}\\)：从 \\(i\\) 到 \\(j\\)、中间点只取自 \\(\\{1,\\ldots,k\\}\\) 的最短路长。要么不经过 \\(k\\)，等于 \\(d_{ij}^{(k-1)}\\)；要么经过，\\(d_{ik}^{(k-1)}+d_{kj}^{(k-1)}\\)。取 min。\\(k=0\\) 为边权（无路 \\(\\infty\\)）。\\(k=n\\) 即全部点对。</p><p>负环：某 \\(d_{ii}\\lt 0\\)。与 Bellman–Ford 检测同现象，记账不同。仍要求没有负环，或至少报告对角负值。本课仍在 P。</p><h3 id="不是「把-dijkstra-跑-n-遍」的别名" tabindex="-1">不是「把 Dijkstra 跑 n 遍」的别名 <a class="header-anchor" href="#不是「把-dijkstra-跑-n-遍」的别名" aria-label="Permalink to &quot;不是「把 Dijkstra 跑 n 遍」的别名&quot;">​</a></h3><p>Floyd 不维护优先队列，不管稀疏。稠密图 \\(E=\\Theta(V^2)\\) 时 \\(V\\) 次 Dijkstra（二叉堆）是 \\(O(V^3\\log V)\\)，Floyd 的 \\(V^3\\) 更干净。稀疏非负全源更该 \\(V\\) 次 Dijkstra。表示课已说矩阵对稠密自然。</p><p><span class="marginnote">Warshall 先做可达性布尔闭包；Floyd 把 min-plus 换成同一骨架。CLRS 25.2 就地滚动 \\(k\\) 维。本课把「中间点」当唯一新对象。</span></p><p><span class="marginnote">术语翻译：全源最短路就是「把每对起点、终点之间的最短距离全部算出来」，产出一张 \\(V\\times V\\) 距离表；单源只从一个固定起点出发。全源当然可以跑 n 遍单源，Floyd 的卖点是三重循环一次算完所有点对。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩阵 \\(W\\)，三重循环 \\(k,i,j\\)：\\(d[i][j]\\leftarrow\\min(d[i][j],d[i][k]+d[k][j])\\)。就地可行，因 \\(k\\) 维只依赖 \\(k-1\\)。前驱可同步更新。</p>',12)),(s(),o(d,null,{default:t(()=>[n(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K0%5B%22%E8%BE%B9%E6%9D%83%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20K%5B%22%E5%85%81%E8%AE%B8%E4%B8%AD%E9%97%B4%E7%82%B9%201..k%22%5D%0A%20%20K%20--%3E%20N%5B%22k%3Dn%EF%BC%9A%E5%85%A8%E6%BA%90%E6%9C%80%E7%9F%AD%E8%B7%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[l("a",{href:"/cs/asymptotic-notation"},"渐近"),r("：\\(\\Theta(V^3)\\) 次加法比较，与稀疏无关。")],-1)),a[4]||(a[4]=l("p",null,[l("span",{class:"marginnote"},"数字实例：\\(V=100\\) 的稠密图，\\(V^3=10^6\\) 次比较瞬间跑完，\\(100\\times100\\) 矩阵只占一万个单元。换成 \\(V=10^5\\) 的稀疏图，\\(V^3=10^{15}\\) 是天文数字——这时该跑 \\(V\\) 次 Dijkstra，让复杂度跟着边数 \\(E\\) 走。")],-1)),a[5]||(a[5]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=l("p",null,"min-plus 半环上的「乘法」是路径拼接。可达性把 min-plus 换成或-与，即 Warshall。后课动态规划会抽象最优子结构；本课已是实例，一般模板仍后置，以免图算法课变成 DP 绪论。",-1)),(s(),o(d,null,{default:t(()=>[n(e,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22k%20%E8%BD%AE%3A%20i%20%E5%88%B0%20j%20%E5%85%81%E8%AE%B8%E5%80%9F%E9%81%93%20k%22%5D%20--%3E%20A%5B%22%E6%97%A7%E8%B7%AF%3A%20d%5Bi%5D%5Bj%5D%20%3D%207%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%96%B0%E8%B7%AF%3A%20d%5Bi%5D%5Bk%5D%20%2B%20d%5Bk%5D%5Bj%5D%20%3D%203%20%2B%202%20%3D%205%22%5D%0A%20%20A%20--%3E%20M%7B%22%E5%8F%96%20min%22%7D%0A%20%20B%20--%3E%20M%0A%20%20M%20--%3E%7C%225%20%3C%207%22%7C%20U%5B%22%E6%9B%B4%E6%96%B0%20d%5Bi%5D%5Bj%5D%20%3D%205%22%5D%0A%20%20M%20--%3E%7C%22%E6%97%A7%E8%B7%AF%E4%B8%8D%E6%9B%B4%E9%95%BF%22%7C%20K%5B%22%E4%BF%9D%E6%8C%81%E4%B8%8D%E5%8F%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">直觉类比：递推像「逐个城市通航」——第 k 轮后，行程只允许中转前 k 个城市。每新开放一个城市，就检查所有城市对：借道它是否更近？n 轮后全部城市开放，表里留下的就是真正的最短路。</span></p><p>路径条数、最长简单路不能套同一三重循环：最长简单路会环、会指数。本课只 min 路径权。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不加速稀疏。不处理负环上的「最短」定义。也不写 Johnson 算法（重新赋权再 Dijkstra）——那是稀疏全源的另一出口，不在本课。空间 \\(\\Theta(V^2)\\) 矩阵必须扛住。</p><p>后课默认：稠密全源可用 Floyd \\(\\Theta(V^3)\\)。生成树问题换成无向边权的另一套最优，不是点对距离。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(d_{ij}^{(k)}\\) 对中间点集合递推，\\(O(V^3)\\) 全源。</li><li>对角负值报告负环。</li><li>稀疏非负全源更宜多次 Dijkstra。</li><li>出处：Floyd, 1962；Warshall, 1962；CLRS 第 25.2 节。</li></ul>',7))])}const c=p(h,[["render",k]]);export{_ as __pageData,c as default};
